221	func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
222		repo, err := openRepository(ctx)
223		if err != nil {
224			return fmt.Errorf("not a git repository: %w", err)
225		}
226	
227		v1Store := checkpoint.NewGitStore(repo)
228		v2Store := checkpoint.NewV2GitStore(repo, strategy.ResolveCheckpointURL(ctx, "origin"))
229		preferCheckpointsV2 := settings.IsCheckpointsV2Enabled(ctx)
230	
231		// First, try to find in committed checkpoints by checkpoint ID prefix
232		committed, err := listCommittedForExplain(ctx, v1Store, v2Store, preferCheckpointsV2)
233		if err != nil {
234			return fmt.Errorf("failed to list checkpoints: %w", err)
235		}
236	
237		// Collect all matching checkpoint IDs to detect ambiguity
238		var matches []id.CheckpointID
239		for _, info := range committed {
240			if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
241				matches = append(matches, info.CheckpointID)
242			}
243		}
244	
245		var fullCheckpointID id.CheckpointID
246		switch len(matches) {
247		case 0:
248			// Not found in committed, try temporary checkpoints by git SHA
249			if generate {
250				return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
251			}
252			output, found := explainTemporaryCheckpoint(ctx, w, repo, v1Store, checkpointIDPrefix, verbose, full, rawTranscript)
253			if found {
254				outputExplainContent(w, output, noPager)
255				return nil
256			}
257			// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
258			if output != "" {
259				return errors.New(output)
260			}
261			return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
262		case 1:
263			fullCheckpointID = matches[0]
264		default:
265			// Ambiguous prefix - show up to 5 examples
266			examples := make([]string, 0, 5)
267			for i := 0; i < len(matches) && i < 5; i++ {
268				examples = append(examples, matches[i].String())
269			}
270			return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
271		}
272	
273		// Resolve store and load checkpoint summary with v2 -> v1 fallback.
274		resolvedReader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, fullCheckpointID, v1Store, v2Store, preferCheckpointsV2)
275		if err != nil {
276			return fmt.Errorf("failed to read checkpoint: %w", err)
277		}
278	
279		// For v2 checkpoints in default display modes (not --full, --generate, or
280		// --raw-transcript), read only from /main — metadata, prompts, and the
281		// compact transcript.jsonl. The raw transcript on /full/* is never needed
282		// for human-readable output and may be unavailable (rotated, not fetched).
283		needsRawTranscript := full || generate || rawTranscript
284		v2Reader, isCheckpointsV2 := resolvedReader.(*checkpoint.V2GitStore)
285	
286		var content *checkpoint.SessionContent
287		if isCheckpointsV2 && !needsRawTranscript {
288			content, err = readV2ContentFromMain(ctx, v2Reader, fullCheckpointID, summary)
289			if err != nil {
290				return fmt.Errorf("failed to read checkpoint content: %w", err)
291			}
292		} else {
293			content, err = readLatestSessionContentForExplain(ctx, resolvedReader, fullCheckpointID, summary)
294			if err != nil {
295				return fmt.Errorf("failed to read checkpoint content: %w", err)
296			}
297		}
298	
299		// Handle summary generation — uses raw transcript.

350		outputExplainContent(w, output, noPager)
